CREATE TEXT SEARCH CONFIGURATION s.cfg4 (PARSER = pg_catalog.default);
ALTER TEXT SEARCH CONFIGURATION s.cfg4 ADD MAPPING FOR asciiword WITH pg_catalog.english_stem;
ALTER TEXT SEARCH CONFIGURATION s.cfg4 ALTER MAPPING FOR asciiword WITH pg_catalog.simple

CREATE TEXT SEARCH CONFIGURATION s.cfg5 (PARSER = pg_catalog.default);
ALTER TEXT SEARCH CONFIGURATION s.cfg5 ADD MAPPING FOR asciiword, word, numword WITH pg_catalog.english_stem;
ALTER TEXT SEARCH CONFIGURATION s.cfg5 ALTER MAPPING FOR asciiword, word WITH pg_catalog.simple

CREATE TEXT SEARCH CONFIGURATION s.cfg8 (PARSER = pg_catalog.default);
ALTER TEXT SEARCH CONFIGURATION s.cfg8 ADD MAPPING FOR asciiword WITH pg_catalog.english_stem;
ALTER TEXT SEARCH CONFIGURATION s.cfg8 DROP MAPPING FOR asciiword

CREATE TEXT SEARCH CONFIGURATION s.cfg10 (PARSER = pg_catalog.default);
ALTER TEXT SEARCH CONFIGURATION s.cfg10 ADD MAPPING FOR asciiword WITH pg_catalog.english_stem;
ALTER TEXT SEARCH CONFIGURATION s.cfg10 DROP MAPPING FOR asciiword, word

CREATE TEXT SEARCH CONFIGURATION s.fullcfg (PARSER = pg_catalog.default);
ALTER TEXT SEARCH CONFIGURATION s.fullcfg ADD MAPPING FOR asciiword WITH pg_catalog.english_stem;
ALTER TEXT SEARCH CONFIGURATION s.fullcfg ADD MAPPING FOR word WITH pg_catalog.english_stem;
ALTER TEXT SEARCH CONFIGURATION s.fullcfg ADD MAPPING FOR numword WITH pg_catalog.simple

CREATE TEXT SEARCH CONFIGURATION s.altcfg2 (PARSER = pg_catalog.default);
ALTER TEXT SEARCH CONFIGURATION s.altcfg2 ADD MAPPING FOR asciiword WITH pg_catalog.english_stem;
ALTER TEXT SEARCH CONFIGURATION s.altcfg2 ADD MAPPING FOR asciiword WITH pg_catalog.simple

CREATE TEXT SEARCH CONFIGURATION s.cfg_dropmapping (PARSER = pg_catalog.default);
ALTER TEXT SEARCH CONFIGURATION s.cfg_dropmapping ADD MAPPING FOR asciiword, word WITH pg_catalog.english_stem;
ALTER TEXT SEARCH CONFIGURATION s.cfg_dropmapping DROP MAPPING FOR asciiword, word

CREATE TEXT SEARCH CONFIGURATION s.cfg_altmap (PARSER = pg_catalog.default);
ALTER TEXT SEARCH CONFIGURATION s.cfg_altmap ADD MAPPING FOR asciiword WITH pg_catalog.english_stem;
ALTER TEXT SEARCH CONFIGURATION s.cfg_altmap ALTER MAPPING FOR asciiword WITH pg_catalog.simple, pg_catalog.english_stem

CREATE TEXT SEARCH CONFIGURATION s.cfg_replace (COPY = pg_catalog.english);
ALTER TEXT SEARCH CONFIGURATION s.cfg_replace ALTER MAPPING REPLACE pg_catalog.english_stem WITH pg_catalog.simple;
ALTER TEXT SEARCH CONFIGURATION s.cfg_replace ALTER MAPPING REPLACE pg_catalog.simple WITH pg_catalog.english_stem

CREATE TEXT SEARCH TEMPLATE s.mytempl6 (LEXIZE = dsimple_lexize);
CREATE TEXT SEARCH DICTIONARY s.dictfromtempl2 (TEMPLATE = s.mytempl6);
CREATE TEXT SEARCH CONFIGURATION s.cfg_from_templ (PARSER = pg_catalog.default);
ALTER TEXT SEARCH CONFIGURATION s.cfg_from_templ ADD MAPPING FOR asciiword WITH s.dictfromtempl2

CREATE TEXT SEARCH CONFIGURATION s.cfg_dropthenreadd (PARSER = pg_catalog.default);
ALTER TEXT SEARCH CONFIGURATION s.cfg_dropthenreadd ADD MAPPING FOR asciiword WITH pg_catalog.english_stem;
ALTER TEXT SEARCH CONFIGURATION s.cfg_dropthenreadd DROP MAPPING FOR asciiword;
ALTER TEXT SEARCH CONFIGURATION s.cfg_dropthenreadd ADD MAPPING FOR asciiword WITH pg_catalog.simple

CREATE TEXT SEARCH TEMPLATE s.mytempl7 (LEXIZE = dsimple_lexize);
CREATE TEXT SEARCH DICTIONARY s.dchain1 (TEMPLATE = s.mytempl7);
CREATE TEXT SEARCH DICTIONARY s.dchain2 (TEMPLATE = pg_catalog.simple);
CREATE TEXT SEARCH PARSER s.pchain (START = prsd_start, GETTOKEN = prsd_nexttoken, END = prsd_end, LEXTYPES = prsd_lextype);
CREATE TEXT SEARCH CONFIGURATION s.cfg_chain (PARSER = s.pchain);
ALTER TEXT SEARCH CONFIGURATION s.cfg_chain ADD MAPPING FOR asciiword WITH s.dchain1, s.dchain2
